viewof n = Inputs.range([1, 50], {value: 10, step: 1, label: "n"})







md`**${n} squared is ${n * n}.**`







Plot.plot({
  marks: [
    Plot.barY(
      Array.from({length: n}, (_, i) =&gt; ({x: i + 1, y: (i + 1) ** 2})),
