1.000 personas, un día
Cada punto representa a 1 de cada 1.000 habitantes. Los puntos se agrupan según la actividad que realizan en cada momento del día — igual que en la visualización original, pero con proporciones reales de la ENUT 2021 en vez de simuladas.

overallRaw = FileAttachment("data/enut_ar/oneday_overall.json").json()







overallByTime = {
  const m = new Map();
  for (const t of new Set(overallRaw.map(d =&gt; d.time))) {
    const rows = overallRaw.filter(d =&gt; d.time === t);
    m.set(t, Object.fromEntries(rows.map(r =&gt; [r.grupo, r.n])));
  }
  return m;
}







overallTimes = [...overallByTime.keys()].sort()







// "Traslados" (Traveling) sits at the hub, like the reference visualization
// -- everyone passes through it on their way between other activities.
// The rest are arranged in a ring, with more radius given to the bigger
// categories (Dormir especially, since sleep alone can hold ~950/1000 dots).
centroids = {
  const cx = 550, cy = 380;
  const ring = [
    ["Dormir", 320],
    ["Ocio", 270],
    ["Trabajo", 270],
    ["Domésticas", 270],
    ["Comer y beber", 250],
    ["Cuidado personal", 210],
    ["Educación", 195],
    ["Cuidado", 210],
    ["Voluntarias", 195],
    ["Sin clasificar", 195]
  ];
  const result = {"Traslados": [cx, cy]};
  ring.forEach(([g, r], i) =&gt; {
    const angle = (i / ring.length) * 2 * Math.PI - Math.PI / 2;
    result[g] = [cx + r * Math.cos(angle), cy + r * Math.sin(angle)];
  });
  return result;
}







oneDayViz = {
  const width = 1100, height = 800;
  const colorFor = Object.fromEntries(grupoOrder.map((g, i) =&gt; [g, grupoColors[i]]));

  function formatTime(t) {
    const [h, m] = t.split(":").map(Number);
    const period = h &lt; 12 ? "am" : "pm";
    let h12 = h % 12;
    if (h12 === 0) h12 = 12;
    return `${h12}:${String(m).padStart(2, "0")}${period}`;
  }

  // build the initial 1000 dots from the first time slot's counts
  function buildDots(t) {
    const counts = overallByTime.get(t);
    const dots = [];
    let idx = 0;
    for (const g of grupoOrder) {
      const n = counts[g] || 0;
      const [cx, cy] = centroids[g];
      for (let i = 0; i &lt; n; i++) {
        dots.push({id: idx++, grupo: g, x: cx + (Math.random() - 0.5) * 20, y: cy + (Math.random() - 0.5) * 20});
      }
    }
    return dots;
  }

  let timeIndex = 0;
  const dots = buildDots(overallTimes[0]);

  const container = html`&lt;div&gt;
    &lt;div style="text-align:center; font-size: 2.2rem; color: var(--bs-secondary-color, #666); font-weight: 300;" class="time-label"&gt;&lt;/div&gt;
    &lt;div style="text-align:center; margin-bottom: 10px;"&gt;
      &lt;button class="btn-play" style="padding: 4px 10px; margin-right: 6px;"&gt;⏸ Pausar&lt;/button&gt;
      &lt;button class="btn-slow" style="padding: 4px 10px; margin-right: 6px;"&gt;Lento&lt;/button&gt;
      &lt;button class="btn-fast" style="padding: 4px 10px;"&gt;Rápido&lt;/button&gt;
    &lt;/div&gt;
    &lt;div style="display:flex; gap: 24px; align-items:flex-start; flex-wrap: wrap;"&gt;
      &lt;div class="chart-holder"&gt;&lt;/div&gt;
      &lt;div class="side-panel" style="flex: 1; min-width: 260px;"&gt;
        &lt;div class="bar-holder"&gt;&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  &lt;/div&gt;`;

  const svg = d3.select(container.querySelector(".chart-holder"))
    .append("svg")
    .attr("width", width)
    .attr("height", height)
    .attr("viewBox", [0, 0, width, height])
    .attr("style", "max-width: 100%; height: auto;");

  const pctLabels = {};
  for (const g of grupoOrder) {
    const [cx, cy] = centroids[g];
    svg.append("text")
      .attr("x", cx).attr("y", cy - 46)
      .attr("text-anchor", "middle")
      .attr("font-size", 12)
      .attr("fill", "currentColor")
      .text(g);
    pctLabels[g] = svg.append("text")
      .attr("x", cx).attr("y", cy - 32)
      .attr("text-anchor", "middle")
      .attr("font-size", 11)
      .attr("fill", "currentColor")
      .attr("opacity", 0.7);
  }

  const circles = svg.selectAll("circle")
    .data(dots, d =&gt; d.id)
    .join("circle")
    .attr("r", 2.4)
    .attr("fill", d =&gt; colorFor[d.grupo])
    .attr("cx", d =&gt; d.x)
    .attr("cy", d =&gt; d.y)
    .attr("opacity", 0.85);

  const sim = d3.forceSimulation(dots)
    .force("x", d3.forceX(d =&gt; centroids[d.grupo][0]).strength(0.1))
    .force("y", d3.forceY(d =&gt; centroids[d.grupo][1]).strength(0.1))
    .force("collide", d3.forceCollide(2.6))
    .alphaDecay(0.03)
    .on("tick", () =&gt; {
      circles.attr("cx", d =&gt; d.x).attr("cy", d =&gt; d.y);
    });

  function updateSidePanel(t) {
    const counts = overallByTime.get(t);
    const ranked = grupoOrder.map(g =&gt; ({grupo: g, n: counts[g] || 0})).sort((a, b) =&gt; b.n - a.n);
    const barHolder = container.querySelector(".bar-holder");
    barHolder.innerHTML = "";
    barHolder.appendChild(Plot.plot({
      width: 340,
      height: 420,
      marginLeft: 150,
      x: {label: "personas de 1.000 →", domain: [0, 1000]},
      y: {domain: ranked.map(d =&gt; d.grupo), label: null},
      marks: [
        Plot.barX(ranked, {y: "grupo", x: "n", fill: d =&gt; colorFor[d.grupo]}),
        Plot.text(ranked, {y: "grupo", x: "n", dx: 20, text: d =&gt; d.n, textAnchor: "start"}),
        Plot.ruleX([0])
      ]
    }));
    for (const g of grupoOrder) {
      pctLabels[g].text(Math.round((counts[g] || 0) / 10) + "%");
    }
    container.querySelector(".time-label").textContent = formatTime(t);
  }

  function advance() {
    timeIndex = (timeIndex + 1) % overallTimes.length;
    const t = overallTimes[timeIndex];
    const target = overallByTime.get(t);

    const currentByGrupo = d3.group(dots, d =&gt; d.grupo);
    const pool = [];
    for (const g of grupoOrder) {
      const arr = currentByGrupo.get(g) || [];
      const want = target[g] || 0;
      for (let i = want; i &lt; arr.length; i++) pool.push(arr[i]);
    }
    let poolIdx = 0;
    for (const g of grupoOrder) {
      const arr = currentByGrupo.get(g) || [];
      const want = target[g] || 0;
      for (let i = arr.length; i &lt; want && poolIdx &lt; pool.length; i++, poolIdx++) {
        pool[poolIdx].grupo = g;
      }
    }

    circles.attr("fill", d =&gt; colorFor[d.grupo]);
    // d3-force's forceX/forceY accessors are only evaluated once, at
    // initialization -- re-setting the forces after mutating d.grupo makes
    // d3 recompute each node's target, otherwise dots keep the old target
    // forever even after their category (and color) has changed.
    sim.force("x", d3.forceX(d =&gt; centroids[d.grupo][0]).strength(0.1));
    sim.force("y", d3.forceY(d =&gt; centroids[d.grupo][1]).strength(0.1));
    sim.alpha(0.7).restart();
    updateSidePanel(t);
  }

  let playing = true;
  let speed = 250;
  let timer = setInterval(advance, speed);
  function restartTimer() {
    clearInterval(timer);
    timer = setInterval(advance, speed);
  }

  container.querySelector(".btn-play").onclick = (e) =&gt; {
    playing = !playing;
    e.target.textContent = playing ? "⏸ Pausar" : "▶ Reanudar";
    if (playing) restartTimer(); else clearInterval(timer);
  };
  container.querySelector(".btn-slow").onclick = () =&gt; { speed = 600; if (playing) restartTimer(); };
  container.querySelector(".btn-fast").onclick = () =&gt; { speed = 100; if (playing) restartTimer(); };

  invalidation.then(() =&gt; clearInterval(timer));

  updateSidePanel(overallTimes[0]);

  return container;
}












Note



Los 1.000 puntos son una muestra proporcional reconstruida a partir de los porcentajes reales por intervalo de 10 minutos — igual que en la visualización original, no son 1.000 personas reales rastreadas individualmente. En cada paso, solo se mueven los puntos que necesitan cambiar de categoría para que el total vuelva a cuadrar con los datos.

El mismo patrón, desagregado por sexo

// Stack manually (y0/y1 per time+sex, in grupoOrder) instead of relying on
// Plot's automatic stack transform -- more predictable and easier to verify.
stacked = {
  const byKey = d3.group(oneDay, d =&gt; `${d.time}|${d.sex}`);
  const rows = [];
  for (const arr of byKey.values()) {
    const base = arr[0];
    let y0 = 0;
    for (const g of grupoOrder) {
      const rec = arr.find(r =&gt; r.grupo === g);
      const pct = rec ? rec.pct : 0;
      const y1 = y0 + pct;
      rows.push({time: base.time, hour: base.hour, sex: base.sex, grupo: g, pct, y0, y1});
      y0 = y1;
    }
  }
  return rows;
}







stackedMujeres = stacked.filter(d =&gt; d.sex === "Mujeres")
stackedVarones = stacked.filter(d =&gt; d.sex === "Varones")
















// Two separate plots (not one faceted with fy:"sex") -- Plot.areaY with
// explicit y1/y2 channels renders incorrectly when combined with fy
// faceting in the Plot version bundled here; two plain plots sidestep it.
dayChart = (data, title) =&gt; Plot.plot({
  title,
  width: 800,
  height: 260,
  marginLeft: 50,
  x: {label: "Hora del día →", domain: [0, 24], ticks: [0, 3, 6, 9, 12, 15, 18, 21, 24], tickFormat: d =&gt; `${d}h`},
  y: {label: "Proporción de la población →", domain: [0, 1], tickFormat: d =&gt; `${Math.round(d * 100)}%`},
  color: {legend: true, domain: grupoOrder, range: grupoColors},
  marks: [
    Plot.areaY(data, {x: "hour", y1: "y0", y2: "y1", fill: "grupo", tip: true}),
    Plot.ruleY([0])
  ]
})







dayChart(stackedMujeres, "Mujeres")







dayChart(stackedVarones, "Varones")












Important



El patrón de sueño (“Dormir”, que domina la madrugada) es casi idéntico entre mujeres y varones. La diferencia salta a la vista durante el día: los varones muestran un pico de “Trabajo” más pronunciado al mediodía, mientras que “Domésticas” y “Cuidado” ocupan una porción visiblemente mayor del día de las mujeres, sin que su “Trabajo” remunerado disminuya tanto durante esas horas — el patrón visual de la doble jornada.

¿Qué tan bien calibrada tienes la intuición sobre la brecha de género en el trabajo doméstico no remunerado? Este juego te muestra cuatro grupos etarios, uno a la vez, y te pide adivinar cuántos minutos más al día dedican las mujeres al trabajo doméstico, comparado con los hombres. Después de cada ronda te mostramos el valor real.
durationRaw = FileAttachment("data/enut/clock_duration.json").json()
colorH = "#5c9e95"
colorM = "#c7a3c0"
accentColor = "#c26b5a"
ageTabOrder = ["Total", "15-24", "25-64", "65+"]
ageTabLabel = ({
  "Total": "Toda la población (15 años y más)",
  "15-24": "Personas de 15 a 24 años",
  "25-64": "Personas de 25 a 64 años",
  "65+": "Personas de 65 años y más"
})
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i &gt; 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
function getHours(activity, ageTab, sex) {
  const rec = durationRaw.find(d =&gt; d.activity === activity && d.age_tab === ageTab && d.sex === sex);
  return rec ? rec.hours : null;
}
function roundData(ageTab) {
  const hoursM = getHours("Trabajo doméstico", ageTab, "Mujeres");
  const hoursH = getHours("Trabajo doméstico", ageTab, "Hombres");
  const gapMin = Math.round((hoursM - hoursH) * 60);
  return { ageTab, hoursM, hoursH, gapMin };
}
function feedback(errorAbs, actualGap) {
  const pct = errorAbs / actualGap;
  if (pct &lt;= 0.1) return { emoji: "🎯", text: "¡Exacto! Tu intuición está muy bien calibrada." };
  if (pct &lt;= 0.25) return { emoji: "👏", text: "Muy cerca." };
  if (pct &lt;= 0.5) return { emoji: "🤔", text: "No tan mal, pero hay una brecha entre tu intuición y el dato." };
  return { emoji: "😮", text: "Bastante lejos — la brecha real sorprende." };
}
game = {
  const wrapper = html`&lt;div&gt;&lt;/div&gt;`;
  const roundBox = html`&lt;div&gt;&lt;/div&gt;`;
  wrapper.appendChild(roundBox);

  let order = shuffle(ageTabOrder);
  let roundIndex = 0;
  let results = [];

  function renderRound() {
    roundBox.innerHTML = "";
    const ageTab = order[roundIndex];
    const data = roundData(ageTab);

    const card = html`&lt;div style="max-width: 640px; margin: 0 auto; padding: 24px; border-radius: 10px; background: color-mix(in srgb, currentColor 5%, transparent);"&gt;&lt;/div&gt;`;

    const progress = html`&lt;div style="font-size: 0.85rem; color: var(--bs-secondary-color, #666); margin-bottom: 4px;"&gt;Ronda ${roundIndex + 1} de ${order.length}&lt;/div&gt;`;
    const group = html`&lt;div style="font-weight: 700; font-size: 1.1rem; margin-bottom: 12px;"&gt;${ageTabLabel[ageTab]}&lt;/div&gt;`;
    const question = html`&lt;div style="margin-bottom: 20px;"&gt;¿Cuántos &lt;strong&gt;minutos más al día&lt;/strong&gt; dedican las &lt;span style="color:${colorM}; font-weight:700;"&gt;mujeres&lt;/span&gt; al trabajo doméstico no remunerado, comparado con los &lt;span style="color:${colorH}; font-weight:700;"&gt;hombres&lt;/span&gt;, en este grupo?&lt;/div&gt;`;

    const inputRow = html`&lt;div style="display:flex; align-items:center; gap: 16px; margin-bottom: 20px; flex-wrap: wrap;"&gt;&lt;/div&gt;`;
    const slider = html`&lt;input type="range" min="0" max="180" step="5" value="60" style="flex: 1; min-width: 200px;"&gt;`;
    const numberBox = html`&lt;input type="number" min="0" max="600" step="1" value="60" style="width: 80px; padding: 4px; text-align: center;"&gt;`;
    const unitLabel = html`&lt;span&gt;min&lt;/span&gt;`;
    slider.oninput = () =&gt; { numberBox.value = slider.value; };
    numberBox.oninput = () =&gt; { if (numberBox.value !== "") slider.value = Math.min(180, Math.max(0, +numberBox.value)); };
    inputRow.appendChild(slider);
    inputRow.appendChild(numberBox);
    inputRow.appendChild(unitLabel);

    const submitBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;"&gt;Comprobar&lt;/button&gt;`;

    card.appendChild(progress);
    card.appendChild(group);
    card.appendChild(question);
    card.appendChild(inputRow);
    card.appendChild(submitBtn);
    roundBox.appendChild(card);

    submitBtn.onclick = () =&gt; {
      const guess = Math.max(0, +numberBox.value || 0);
      results.push({ ageTab, guess, actual: data.gapMin, hoursM: data.hoursM, hoursH: data.hoursH });
      renderReveal(data, guess);
    };
  }

  function renderReveal(data, guess) {
    roundBox.innerHTML = "";
    const card = html`&lt;div style="max-width: 640px; margin: 0 auto; padding: 24px; border-radius: 10px; background: color-mix(in srgb, currentColor 5%, transparent);"&gt;&lt;/div&gt;`;

    const progress = html`&lt;div style="font-size: 0.85rem; color: var(--bs-secondary-color, #666); margin-bottom: 4px;"&gt;Ronda ${roundIndex + 1} de ${order.length}&lt;/div&gt;`;
    const group = html`&lt;div style="font-weight: 700; font-size: 1.1rem; margin-bottom: 12px;"&gt;${ageTabLabel[data.ageTab]}&lt;/div&gt;`;

    const errorAbs = Math.abs(guess - data.gapMin);
    const fb = feedback(errorAbs, data.gapMin);
    const fbBox = html`&lt;div style="font-size: 1.05rem; margin-bottom: 16px;"&gt;&lt;span style="font-size:1.4rem;"&gt;${fb.emoji}&lt;/span&gt; ${fb.text} Adivinaste &lt;strong&gt;${guess} min&lt;/strong&gt;, la brecha real es &lt;strong&gt;${data.gapMin} min&lt;/strong&gt; (te desviaste por ${errorAbs} min).&lt;/div&gt;`;

    // number line comparing guess vs actual
    const niceMax = Math.max(50, Math.ceil((Math.max(guess, data.gapMin) * 1.3) / 10) * 10);
    const svgWidth = 600, svgHeight = 100, x0 = 30, x1 = svgWidth - 30;
    const scale = v =&gt; x0 + (v / niceMax) * (x1 - x0);

    const lineHolder = html`&lt;div style="overflow-x:auto;"&gt;&lt;/div&gt;`;
    const svg = d3.select(lineHolder).append("svg").attr("width", svgWidth).attr("height", svgHeight).attr("viewBox", `0 0 ${svgWidth} ${svgHeight}`);

    svg.append("line").attr("x1", x0).attr("x2", x1).attr("y1", 60).attr("y2", 60).attr("stroke", "#999").attr("stroke-width", 1.5);
    const nTicks = 5;
    for (let i = 0; i &lt;= nTicks; i++) {
      const v = Math.round((niceMax / nTicks) * i);
      const x = scale(v);
      svg.append("line").attr("x1", x).attr("x2", x).attr("y1", 56).attr("y2", 64).attr("stroke", "#999");
      svg.append("text").attr("x", x).attr("y", 78).attr("text-anchor", "middle").attr("font-size", 10).attr("fill", "currentColor").text(v);
    }

    const gx = scale(guess);
    svg.append("line").attr("x1", gx).attr("x2", gx).attr("y1", 30).attr("y2", 60).attr("stroke", "#888").attr("stroke-width", 2).attr("stroke-dasharray", "3,2");
    svg.append("circle").attr("cx", gx).attr("cy", 30).attr("r", 4).attr("fill", "#888");
    svg.append("text").attr("x", gx).attr("y", 20).attr("text-anchor", "middle").attr("font-size", 11).attr("fill", "#888").text("Tu respuesta");

    const ax = scale(data.gapMin);
    svg.append("line").attr("x1", ax).attr("x2", ax).attr("y1", 30).attr("y2", 60).attr("stroke", accentColor).attr("stroke-width", 2.5);
    svg.append("circle").attr("cx", ax).attr("cy", 60).attr("r", 5).attr("fill", accentColor);
    svg.append("text").attr("x", ax).attr("y", 20).attr("text-anchor", "middle").attr("font-size", 11).attr("fill", accentColor).attr("font-weight", 700).text("Real");

    // context bars: hours by sex
    const barsHolder = html`&lt;div style="margin-top: 20px;"&gt;&lt;/div&gt;`;
    const barsSvg = d3.select(barsHolder).append("svg").attr("width", svgWidth).attr("height", 90).attr("viewBox", `0 0 ${svgWidth} 90`);
    const maxHours = Math.max(data.hoursM, data.hoursH) * 1.15;
    const barScale = h =&gt; (h / maxHours) * (svgWidth - 140);
    const rows = [
      { label: "Mujeres", hours: data.hoursM, color: colorM, y: 10 },
      { label: "Hombres", hours: data.hoursH, color: colorH, y: 50 }
    ];
    rows.forEach(r =&gt; {
      barsSvg.append("text").attr("x", 0).attr("y", r.y + 15).attr("font-size", 12).attr("fill", "currentColor").text(r.label);
      barsSvg.append("rect").attr("x", 90).attr("y", r.y).attr("width", barScale(r.hours)).attr("height", 22).attr("fill", r.color).attr("rx", 3);
      const hh = Math.floor(r.hours);
      const mm = Math.round((r.hours - hh) * 60);
      barsSvg.append("text").attr("x", 96 + barScale(r.hours)).attr("y", r.y + 15).attr("font-size", 12).attr("fill", "currentColor").text(`${hh} h ${mm} min`);
    });

    const nextBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;margin-top:20px;"&gt;${roundIndex + 1 &lt; order.length ? "Siguiente ronda →" : "Ver resultado final"}&lt;/button&gt;`;
    nextBtn.onclick = () =&gt; {
      if (roundIndex + 1 &lt; order.length) {
        roundIndex += 1;
        renderRound();
      } else {
        renderSummary();
      }
    };

    card.appendChild(progress);
    card.appendChild(group);
    card.appendChild(fbBox);
    card.appendChild(lineHolder);
    card.appendChild(barsHolder);
    card.appendChild(nextBtn);
    roundBox.appendChild(card);
  }

  function renderSummary() {
    roundBox.innerHTML = "";
    const card = html`&lt;div style="max-width: 640px; margin: 0 auto; padding: 24px; border-radius: 10px; background: color-mix(in srgb, currentColor 5%, transparent);"&gt;&lt;/div&gt;`;

    const title = html`&lt;div style="font-weight: 700; font-size: 1.2rem; margin-bottom: 16px;"&gt;Resultado final&lt;/div&gt;`;

    const table = html`&lt;table style="width:100%; border-collapse: collapse; margin-bottom: 16px;"&gt;&lt;/table&gt;`;
    const thead = html`&lt;thead&gt;&lt;tr&gt;
      &lt;th style="text-align:left; padding:6px; border-bottom: 1px solid #999;"&gt;Grupo&lt;/th&gt;
      &lt;th style="text-align:right; padding:6px; border-bottom: 1px solid #999;"&gt;Tu respuesta&lt;/th&gt;
      &lt;th style="text-align:right; padding:6px; border-bottom: 1px solid #999;"&gt;Real&lt;/th&gt;
      &lt;th style="text-align:right; padding:6px; border-bottom: 1px solid #999;"&gt;Diferencia&lt;/th&gt;
    &lt;/tr&gt;&lt;/thead&gt;`;
    table.appendChild(thead);
    const tbody = html`&lt;tbody&gt;&lt;/tbody&gt;`;
    let totalError = 0;
    results.forEach(r =&gt; {
      const err = Math.abs(r.guess - r.actual);
      totalError += err;
      const row = html`&lt;tr&gt;
        &lt;td style="padding:6px; border-bottom: 1px solid #eee;"&gt;${ageTabLabel[r.ageTab]}&lt;/td&gt;
        &lt;td style="text-align:right; padding:6px; border-bottom: 1px solid #eee;"&gt;${r.guess} min&lt;/td&gt;
        &lt;td style="text-align:right; padding:6px; border-bottom: 1px solid #eee;"&gt;${r.actual} min&lt;/td&gt;
        &lt;td style="text-align:right; padding:6px; border-bottom: 1px solid #eee;"&gt;${err} min&lt;/td&gt;
      &lt;/tr&gt;`;
      tbody.appendChild(row);
    });
    table.appendChild(tbody);

    const avgError = Math.round(totalError / results.length);
    const closing = html`&lt;div style="margin-bottom: 20px;"&gt;Tu error promedio fue de &lt;strong&gt;${avgError} minutos&lt;/strong&gt; por ronda. ${avgError &lt;= 15 ? "Muy buena intuición sobre la brecha de género en el trabajo doméstico." : avgError &lt;= 35 ? "Una intuición razonable, aunque la brecha real suele ser más marcada de lo que se piensa." : "La brecha real es más grande de lo que la mayoría intuye — así es la desigualdad en el trabajo doméstico no remunerado."}&lt;/div&gt;`;

    const replayBtn = html`&lt;button style="padding:8px 20px;border-radius:4px;border:1px solid #5c9e95;background:#5c9e95;color:white;cursor:pointer;font-size:0.95rem;"&gt;Jugar de nuevo&lt;/button&gt;`;
    replayBtn.onclick = () =&gt; {
      order = shuffle(ageTabOrder);
      roundIndex = 0;
      results = [];
      renderRound();
    };

    card.appendChild(title);
    card.appendChild(table);
    card.appendChild(closing);
    card.appendChild(replayBtn);
    roundBox.appendChild(card);
  }

  renderRound();
  return wrapper;
}

